// ──────────────────────────── Constants ──────────────────────────────

/// Wire size of a Pulse in bytes. Always 128.
#[napi]
pub const PULSE_WIRE_SIZE: u32 = CORE_PULSE_WIRE_SIZE as u32;

/// Maximum envelope payload size in bytes (1315) — set by the MTU
/// (1472) minus the framing header (153) and CRC32C trailer (4).
#[napi]
pub const MAX_ENVELOPE: u32 = UDP_MAX_ENVELOPE as u32;

/// Pre-payload header size in bytes (153) — `magic + version + seq +
/// send_ns + pulse + envelope_len`.
#[napi]
pub const HEADER_BYTES: u32 = UDP_HEADER_BYTES as u32;

// ──────────────────────────── Instruction ────────────────────────────

/// Deterministic opcode carried in `Pulse.instruction`.
#[napi]
pub enum Instruction {
    /// 0x0000: Blank slate. Zeroed memory or empty buffer slot.
    Null = 0x0000,
    /// 0x0001: Liveness signal.
    Heartbeat = 0x0001,
    /// 0x0010: Generic data signal — envelope_ref points to a payload.
    Data = 0x0010,
}

// ────────────────────────────── Pulse ────────────────────────────────

/// 128-byte cache-aligned Pulse — the wire-format atomic unit.
///
/// Construct with `new Pulse()` for a zeroed Pulse, or with
/// `Pulse.fromBytes(buffer)` to deserialize a 128-byte buffer.
/// Serialize back via `pulse.toBytes()`.
#[napi]
pub struct Pulse {
    inner: RustPulse,
}

#[napi]
impl Pulse {
    /// Construct a zeroed Pulse (`instruction === Instruction.Null`).
    #[napi(constructor)]
    pub fn new() -> Self {
        Self {
            inner: RustPulse::zeroed(),
        }
    }

    /// Reinterpret a 128-byte Buffer as a Pulse. Throws if the input
    /// is not exactly 128 bytes.
    #[napi(factory)]
    pub fn from_bytes(bytes: Buffer) -> Result<Self> {
        RustPulse::from_bytes(&bytes)
            .map(|p| Self { inner: p })
            .ok_or_else(|| {
                Error::new(
                    Status::InvalidArg,
                    format!(
                        "Pulse.fromBytes expects {} bytes, got {}",
                        CORE_PULSE_WIRE_SIZE,
                        bytes.len()
                    ),
                )
            })
    }

    /// Serialize this Pulse into a 128-byte Buffer (copy).
    #[napi]
    pub fn to_bytes(&self) -> Buffer {
        Buffer::from(self.inner.as_bytes().to_vec())
    }

    /// Deterministic instruction code (0x0000 / 0x0001 / 0x0010).
    #[napi(getter)]
    pub fn instruction(&self) -> u32 {
        self.inner.instruction as u32
    }
    #[napi(setter)]
    pub fn set_instruction(&mut self, v: u32) {
        self.inner.instruction = v as u16;
    }

    /// Execution scope (path index or memory region).
    #[napi(getter)]
    pub fn scope(&self) -> u32 {
        self.inner.scope
    }
    #[napi(setter)]
    pub fn set_scope(&mut self, v: u32) {
        self.inner.scope = v;
    }

    /// `monotonic_nanos` timestamp at Pulse creation. Returned as
    /// BigInt to preserve u64 precision.
    #[napi(getter)]
    pub fn monotonic_nanos(&self) -> BigInt {
        BigInt::from(self.inner.monotonic_nanos)
    }
    #[napi(setter)]
    pub fn set_monotonic_nanos(&mut self, v: BigInt) -> Result<()> {
        self.inner.monotonic_nanos = bigint_u64(&v, "monotonicNanos")?;
        Ok(())
    }

    /// Replay-defence countdown. Returned as BigInt.
    #[napi(getter)]
    pub fn chain_step(&self) -> BigInt {
        BigInt::from(self.inner.chain_step)
    }
    #[napi(setter)]
    pub fn set_chain_step(&mut self, v: BigInt) -> Result<()> {
        self.inner.chain_step = bigint_u64(&v, "chainStep")?;
        Ok(())
    }

    /// 16-byte node identifier. Returned as a Buffer (copy).
    #[napi(getter)]
    pub fn origin_id(&self) -> Buffer {
        Buffer::from(self.inner.origin_id.to_vec())
    }
    #[napi(setter)]
    pub fn set_origin_id(&mut self, v: Buffer) -> Result<()> {
        if v.len() != 16 {
            return Err(Error::new(
                Status::InvalidArg,
                format!("origin_id must be exactly 16 bytes (got {})", v.len()),
            ));
        }
        self.inner.origin_id.copy_from_slice(&v);
        Ok(())
    }

    /// 16-byte envelope reference (truncated BLAKE3 of the envelope
    /// id). All zeros means no envelope is attached.
    #[napi(getter)]
    pub fn envelope_ref(&self) -> Buffer {
        Buffer::from(self.inner.envelope_ref.to_vec())
    }
    #[napi(setter)]
    pub fn set_envelope_ref(&mut self, v: Buffer) -> Result<()> {
        if v.len() != 16 {
            return Err(Error::new(
                Status::InvalidArg,
                format!("envelope_ref must be exactly 16 bytes (got {})", v.len()),
            ));
        }
        self.inner.envelope_ref.copy_from_slice(&v);
        Ok(())
    }

    /// The envelope store cursor a Data pulse names (where the envelope its
    /// `envelopeRef` names was stored), or `null` when it names none.
    #[napi(getter)]
    pub fn store_cursor(&self) -> Option<BigInt> {
        self.inner.store_cursor().map(BigInt::from)
    }

    /// True iff `envelopeRef` is non-zero.
    #[napi]
    pub fn has_envelope(&self) -> bool {
        self.inner.has_envelope()
    }
}

impl Default for Pulse {
    fn default() -> Self {
        Self::new()
    }
}

// ───────────────────────── Recv result types ──────────────────────────

/// Object returned by `Receiver.recv()` — owned envelope copy.
#[napi(object)]
pub struct RecvResult {
    /// 128-byte Pulse wire bytes — pass to `Pulse.fromBytes` for typed access.
    pub pulse_bytes: Buffer,
    /// Envelope payload (freshly allocated).
    pub envelope: Buffer,
    /// Wire-stamped sequence number.
    pub seq: BigInt,
    /// Sender-stamped quanta timestamp in nanoseconds.
    pub send_ns: BigInt,
    /// Peer that sent the datagram (`"ip:port"`).
    pub peer: String,
}

/// Object returned by `Receiver.recvInto(buf)` — caller owns the buffer.
#[napi(object)]
pub struct RecvIntoResult {
    /// 128-byte Pulse wire bytes.
    pub pulse_bytes: Buffer,
    /// Number of bytes written into `buf` (envelope length).
    pub env_len: u32,
    /// Wire-stamped sequence number.
    pub seq: BigInt,
    /// Sender-stamped quanta timestamp in nanoseconds.
    pub send_ns: BigInt,
    /// Peer that sent the datagram (`"ip:port"`).
    pub peer: String,
}

// ────────────────────────────── Sender ───────────────────────────────

/// UDP sender for `pulse-wire-udp` frames.
#[napi]
pub struct Sender {
    inner: RustSender,
}

#[napi]
impl Sender {
    /// Bind a sender to `localAddr` (e.g. `"127.0.0.1:0"` to let the
    /// OS pick a port).
    #[napi(factory)]
    pub fn bind(local_addr: String) -> Result<Self> {
        RustSender::bind(&local_addr)
            .map(|s| Self { inner: s })
            .map_err(map_sender_err)
    }

    /// Set the default destination for `send()`.
    #[napi]
    pub fn connect(&mut self, dest: String) -> Result<()> {
        self.inner.connect(&dest).map_err(map_sender_err)
    }

    /// Send one frame to the connected destination. Returns the
    /// monotonic per-instance sequence number stamped on the wire.
    ///
    /// `strict`: napi-rs checks that `pulse` is a `Pulse` instance
    /// before unwrapping it. Without the check napi-rs unwraps any
    /// wrapped object's native pointer as a `Pulse`, so a `Receiver`
    /// (or any other class) passed here would have its heap bytes read
    /// as a Pulse and sent on the wire — and a debug build aborts on
    /// the misaligned read. With it, a non-`Pulse` argument is refused
    /// with "Value is not instanceof class Pulse".
    #[napi(strict)]
    pub fn send(&mut self, send_ns: BigInt, pulse: &Pulse, envelope: Buffer) -> Result<BigInt> {
        let send_ns_u64 = bigint_u64(&send_ns, "sendNs")?;
        self.inner
            .send(send_ns_u64, &pulse.inner, &envelope)
            .map(BigInt::from)
            .map_err(map_sender_err)
    }

    /// Send one frame to `dest`, overriding any default destination.
    ///
    /// `strict`: as in [`Self::send`], the `pulse` argument is checked
    /// to be a `Pulse` instance before it is unwrapped.
    #[napi(strict)]
    pub fn send_to(
        &mut self,
        send_ns: BigInt,
        pulse: &Pulse,
        envelope: Buffer,
        dest: String,
    ) -> Result<BigInt> {
        let send_ns_u64 = bigint_u64(&send_ns, "sendNs")?;
        let addr: SocketAddr = dest.parse().map_err(|e: std::net::AddrParseError| {
            Error::new(Status::InvalidArg, format!("invalid socket address: {e}"))
        })?;
        self.inner
            .send_to(send_ns_u64, &pulse.inner, &envelope, addr)
            .map(BigInt::from)
            .map_err(map_sender_err)
    }

    /// Local socket address (`"ip:port"`) the sender is bound to.
    #[napi]
    pub fn local_addr(&self) -> Result<String> {
        self.inner
            .local_addr()
            .map(|a| a.to_string())
            .map_err(|e| Error::new(Status::GenericFailure, e.to_string()))
    }

    /// Maximum envelope payload size in bytes.
    #[napi]
    pub fn max_envelope() -> u32 {
        UDP_MAX_ENVELOPE as u32
    }

    /// Next-to-be-sent sequence counter (diagnostic).
    #[napi]
    pub fn next_seq(&self) -> BigInt {
        BigInt::from(self.inner.next_seq())
    }
}

// ───────────────────────────── Receiver ──────────────────────────────

/// Shortest wait a receive with a deadline makes: a socket read timeout
/// cannot be zero, so a deadline already passed still reads once, for a
/// frame already queued.
const SHORTEST_WAIT: Duration = Duration::from_micros(1);

/// A receiver and the read timeout its socket has now, behind the mutex a
/// `Receiver` shares with its [`Waiter`] thread.
struct UdpEnd {
    rx: RustReceiver,
    /// The socket's read timeout, set only when a receive needs another.
    applied: Option<Duration>,
}

impl UdpEnd {
    fn new(rx: RustReceiver) -> Self {
        Self { rx, applied: None }
    }

    /// Give the socket the read timeout `timeout` (`None`: none).
    fn time_out_after(
        &mut self,
        timeout: Option<Duration>,
    ) -> std::result::Result<(), RustReceiverError> {
        if self.applied != timeout {
            self.rx.set_read_timeout(timeout)?;
            self.applied = timeout;
        }
        Ok(())
    }
}

/// UDP receiver for `pulse-wire-udp` frames.
///
/// `recv` and `recvInto` wait on the event loop; `recvAsync` waits on a
/// thread of the receiver's own and returns a promise.
#[napi]
pub struct Receiver {
    end: Arc<Mutex<UdpEnd>>,
    /// The timeout `setReadTimeoutMs` set: how long `recv` and `recvInto`
    /// wait, and `recvAsync` when given none.
    read_timeout: Option<Duration>,
    /// The socket's address, read once at bind: `localAddr` never waits for
    /// a receive in progress.
    local_addr: std::result::Result<String, String>,
    /// The thread `recvAsync` waits on.
    waiter: Waiter,
}

#[napi]
impl Receiver {
    /// Bind a receiver to `localAddr`.
    #[napi(factory)]
    pub fn bind(local_addr: String) -> Result<Self> {
        RustReceiver::bind(&local_addr)
            .map(Self::with)
            .map_err(|e| Error::new(Status::GenericFailure, e.to_string()))
    }

    /// Set how long `recv` and `recvInto` wait for a frame, in
    /// milliseconds, and `recvAsync` when given no timeout. Pass `null` /
    /// `undefined` (or omit) for no timeout (wait until a frame comes).
    /// Throws `InvalidArg` for 0.
    #[napi]
    pub fn set_read_timeout_ms(&mut self, millis: Option<u32>) -> Result<()> {
        if millis == Some(0) {
            return Err(Error::new(
                Status::InvalidArg,
                "a read timeout must be at least 1 ms; pass null for none",
            ));
        }
        self.read_timeout = millis.map(|m| Duration::from_millis(u64::from(m)));
        Ok(())
    }

    /// Wait on the socket and return one decoded frame. Throws an error
    /// whose message contains `"timeout"` if the read timeout elapses, and
    /// `Busy` while a `recvAsync` on this receiver has not settled.
    ///
    /// Waits on the event loop: no timer, I/O callback or promise runs
    /// until it returns. `recvAsync` does not.
    #[napi]
    pub fn recv(&mut self) -> Result<RecvResult, Code> {
        let timeout = self.read_timeout;
        let mut end = self.idle_end()?;
        end.time_out_after(timeout).map_err(map_receiver_err)?;
        match end.rx.recv() {
            Ok(frame) => Ok(recv_result(frame)),
            Err(e) => Err(map_receiver_err(e)),
        }
    }

    /// Receive one frame, writing the envelope into `buf` in place.
    /// `buf` must be at least as large as the incoming envelope;
    /// otherwise the call throws and the frame is consumed. Waits on the
    /// event loop, as `recv` does, and throws `Busy` as it does.
    #[napi]
    pub fn recv_into(&mut self, mut buf: Buffer) -> Result<RecvIntoResult, Code> {
        let timeout = self.read_timeout;
        let mut end = self.idle_end()?;
        end.time_out_after(timeout).map_err(map_receiver_err)?;
        let slice: &mut [u8] = &mut buf;
        match end.rx.recv_into(slice) {
            Ok((pulse, env_len, meta)) => Ok(RecvIntoResult {
                pulse_bytes: Buffer::from(pulse.as_bytes().to_vec()),
                env_len: env_len as u32,
                seq: BigInt::from(meta.seq),
                send_ns: BigInt::from(meta.send_ns),
                peer: meta.peer.to_string(),
            }),
            Err(e) => Err(map_receiver_err(e)),
        }
    }

    /// `recv` off the event loop: a promise of the next frame, as `recv`
    /// returns it, or of `null` if none came within `timeoutMs`
    /// milliseconds, counted from this call. Without `timeoutMs`, the
    /// timeout `setReadTimeoutMs` set, and without that, no limit; a
    /// receive with no limit keeps Node running until a frame comes. `0`
    /// takes a frame already queued and waits for none. Rejects with the
    /// error `recv` would throw for a socket error or a frame that does not
    /// decode. Receives asked for together settle in order, each with the
    /// next frame.
    #[napi(ts_return_type = "Promise<RecvResult | null>")]
    pub fn recv_async(&mut self, env: Env, timeout_ms: Option<u32>) -> Result<JsObject> {
        let timeout = match timeout_ms {
            Some(ms) => Some(Duration::from_millis(u64::from(ms))),
            None => self.read_timeout,
        };
        let deadline = timeout.and_then(|t| Instant::now().checked_add(t));
        let shared = Arc::clone(&self.end);
        self.waiter.run(
            &env,
            move || {
                let mut end = shared.lock().unwrap_or_else(PoisonError::into_inner);
                let left = deadline.map(|d| {
                    d.saturating_duration_since(Instant::now())
                        .max(SHORTEST_WAIT)
                });
                end.time_out_after(left).map_err(map_receiver_err)?;
                match end.rx.recv() {
                    Ok(frame) => Ok(Some(frame)),
                    Err(e) if e.is_timeout() => Ok(None),
                    Err(e) => Err(map_receiver_err(e)),
                }
            },
            |_env, frame: Option<(RustPulse, Vec<u8>, RustRecvMeta)>| Ok(frame.map(recv_result)),
        )
    }

    /// Local socket address (`"ip:port"`) the receiver is bound to.
    #[napi]
    pub fn local_addr(&self) -> Result<String> {
        self.local_addr
            .clone()
            .map_err(|e| Error::new(Status::GenericFailure, e))
    }

    /// Maximum envelope payload size in bytes.
    #[napi]
    pub fn max_envelope() -> u32 {
        UDP_MAX_ENVELOPE as u32
    }
}

impl Receiver {
    fn with(rx: RustReceiver) -> Self {
        let local_addr = rx
            .local_addr()
            .map(|a| a.to_string())
            .map_err(|e| e.to_string());
        Self {
            end: Arc::new(Mutex::new(UdpEnd::new(rx))),
            read_timeout: None,
            local_addr,
            waiter: Waiter::new("pulse-wire recv"),
        }
    }

    /// The receiver, for a synchronous receive: `Busy` while a `recvAsync`
    /// has not settled, rather than waiting on the event loop for the lock
    /// its thread holds.
    fn idle_end(&self) -> Result<MutexGuard<'_, UdpEnd>, Code> {
        if self.waiter.pending() > 0 {
            return Err(busy("Receiver"));
        }
        match self.end.try_lock() {
            Ok(end) => Ok(end),
            Err(TryLockError::Poisoned(poisoned)) => Ok(poisoned.into_inner()),
            Err(TryLockError::WouldBlock) => Err(busy("Receiver")),
        }
    }
}

fn recv_result((pulse, envelope, meta): (RustPulse, Vec<u8>, RustRecvMeta)) -> RecvResult {
    RecvResult {
        pulse_bytes: Buffer::from(pulse.as_bytes().to_vec()),
        envelope: Buffer::from(envelope),
        seq: BigInt::from(meta.seq),
        send_ns: BigInt::from(meta.send_ns),
        peer: meta.peer.to_string(),
    }
}

fn busy(what: &str) -> napi::Error<Code> {
    coded(
        Code::Busy,
        format!(
            "a recvAsync on this {what} has not settled; await it before a synchronous receive"
        ),
    )
}

// ───────────────────────────── bindPair ──────────────────────────────

/// The `Sender` and `Receiver` `bindPair` returns, sharing one socket.
#[napi(object, object_from_js = false)]
pub struct SocketPair {
    /// Sends from the shared socket.
    pub sender: Sender,
    /// Receives on the shared socket.
    pub receiver: Receiver,
}

/// Bind one UDP socket at `localAddr` and return a `Sender` and a
/// `Receiver` that share it, so datagrams go out from the port replies
/// come back to. A peer behind a home router (NAT) needs this: the router
/// opens a path back only to the port a datagram left from, and often only
/// for replies from the address it went to, so a program that sends and
/// receives on two sockets never hears its replies.
#[napi]
pub fn bind_pair(local_addr: String) -> Result<SocketPair> {
    let socket = std::net::UdpSocket::bind(&local_addr)
        .map_err(|e| Error::new(Status::GenericFailure, e.to_string()))?;
    let clone = socket
        .try_clone()
        .map_err(|e| Error::new(Status::GenericFailure, e.to_string()))?;
    Ok(SocketPair {
        sender: Sender {
            inner: RustSender::from_socket(clone),
        },
        receiver: Receiver::with(RustReceiver::from_socket(socket)),
    })
}

// ─────────────────────────── error mapping ───────────────────────────

fn map_sender_err(e: RustSenderError) -> Error {
    match &e {
        RustSenderError::Io(_) => Error::new(Status::GenericFailure, e.to_string()),
        RustSenderError::Encode(_) | RustSenderError::NoDestination => {
            Error::new(Status::InvalidArg, e.to_string())
        }
        _ => Error::new(Status::GenericFailure, e.to_string()),
    }
}

/// A receive's error, with the codes it had before `Code` existed:
/// `GenericFailure` for a socket error or a timeout, `InvalidArg` for a
/// frame that does not decode or fit.
fn map_receiver_err(e: RustReceiverError) -> napi::Error<Code> {
    if e.is_timeout() {
        return coded(Code::GenericFailure, format!("recv timeout: {e}"));
    }
    match &e {
        RustReceiverError::Io(_) => coded(Code::GenericFailure, e.to_string()),
        RustReceiverError::Decode(_) | RustReceiverError::BufferTooSmall { .. } => {
            coded(Code::InvalidArg, e.to_string())
        }
        _ => coded(Code::GenericFailure, e.to_string()),
    }
}

/// A BigInt as a `u64`. napi's `get_u64` hands back the magnitude of a
/// negative BigInt and the low 64 bits of one past `u64::MAX`, only flagging
/// both, so `-5n` would silently become 5; such a value is refused instead.
pub(crate) fn bigint_u64(v: &BigInt, what: &str) -> Result<u64> {
    let (negative, value, lossless) = v.get_u64();
    if negative || !lossless {
        return Err(Error::new(
            Status::InvalidArg,
            format!("{what} must be a BigInt from 0 to 2^64 - 1"),
        ));
    }
    Ok(value)
}
